import{_ as o,o as a,c as t,ag as r}from"./chunks/framework.wGDfT7ie.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),n={name:"troubleshooting.md"};function s(i,e,l,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Common issues and where to get help.</p><h2 id="chunkloaderror-css-not-loading" tabindex="-1">ChunkLoadError / CSS not loading <a class="header-anchor" href="#chunkloaderror-css-not-loading" aria-label="Permalink to &quot;ChunkLoadError / CSS not loading&quot;">​</a></h2><p>After a deploy, the app may serve cached old chunks. Try:</p><ul><li><strong>Hard refresh:</strong> Ctrl+Shift+R (Windows/Linux) or Cmd+Shift+R (Mac).</li><li><strong>Clear site data:</strong> In browser settings, clear data for zkde.fi (cookies, cache).</li><li>If chunks return 404, ensure a full frontend rebuild and deploy so chunk filenames match the current build.</li></ul><h2 id="_404-on-docs" tabindex="-1">404 on /docs <a class="header-anchor" href="#_404-on-docs" aria-label="Permalink to &quot;404 on /docs&quot;">​</a></h2><p>Use <strong>zkde.fi/docs</strong> or <strong>zkde.fi/docs/</strong> (with trailing slash). If you still get 404, the server may not be serving the docs path. On nginx, ensure <code>location /docs/</code> is configured with alias to the built docs (see <a href="/docs/deploying-zkde-fi.html">Deploying zkde.fi</a>).</p><h2 id="transaction-errors" tabindex="-1">Transaction errors <a class="header-anchor" href="#transaction-errors" aria-label="Permalink to &quot;Transaction errors&quot;">​</a></h2><h3 id="u256-sub-overflow" tabindex="-1">u256_sub Overflow <a class="header-anchor" href="#u256-sub-overflow" aria-label="Permalink to &quot;u256_sub Overflow&quot;">​</a></h3><p>Usually a balance or amount mismatch (e.g. wrong decimals or trying to spend more than available). Check the amounts you enter and your token balance. Ensure you&#39;re on Starknet Sepolia and that the token addresses match the network.</p><h3 id="not-initialized" tabindex="-1">NOT_INITIALIZED <a class="header-anchor" href="#not-initialized" aria-label="Permalink to &quot;NOT_INITIALIZED&quot;">​</a></h3><p>The pool or contract is not initialized on the network you&#39;re using. Ensure you&#39;re on <strong>Starknet Sepolia</strong> and that the pool/strategy is active. If you deployed recently, wait for indexing.</p><h3 id="requested-contract-address-is-not-deployed" tabindex="-1">Requested contract address ... is not deployed <a class="header-anchor" href="#requested-contract-address-is-not-deployed" aria-label="Permalink to &quot;Requested contract address ... is not deployed&quot;">​</a></h3><p>The contract at that address is not deployed on the network your wallet is using. Switch to Starknet Sepolia and confirm the app is pointing to Sepolia contracts.</p><h2 id="ekubo-api-unavailable-ekubo-chain-id-not-set" tabindex="-1">Ekubo API unavailable / EKUBO_CHAIN_ID not set <a class="header-anchor" href="#ekubo-api-unavailable-ekubo-chain-id-not-set" aria-label="Permalink to &quot;Ekubo API unavailable / EKUBO_CHAIN_ID not set&quot;">​</a></h2><p>Positions may show &quot;pending&quot; or &quot;Ekubo API unavailable&quot; when the backend cannot reach Ekubo (e.g. for position data). Check backend environment (Ekubo RPC/API config). As a user, you can retry later or check <a href="/docs/faq.html">FAQ</a> and support channels.</p><h2 id="where-to-get-help" tabindex="-1">Where to get help <a class="header-anchor" href="#where-to-get-help" aria-label="Permalink to &quot;Where to get help&quot;">​</a></h2><ul><li><strong>GitHub Issues:</strong> <a href="https://github.com/obsqra-labs/zkdefi/issues" target="_blank" rel="noreferrer">Report bugs or request features</a></li><li><strong>Twitter:</strong> <a href="https://twitter.com/obsqralabs" target="_blank" rel="noreferrer">@obsqralabs</a></li></ul><p>See also <a href="/docs/developers.html">Developers</a>, <a href="/docs/api-overview.html">API overview</a>, and <a href="/docs/faq.html">FAQ</a>.</p><p>Next: <a href="/docs/faq.html">FAQ</a> | <a href="/docs/developers.html">Developers</a></p>',20)])])}const b=o(n,[["render",s]]);export{p as __pageData,b as default};
